INSERT INTO `incidents` VALUES (2,3,'2026-10-12 12:52:43','[SIMULASI] Connection Loss','[DATA UJI / SIMULASI KEGAGALAN] Kabel LAN uplink lab dicabut untuk pengujian failure simulation. Monitoring engine mendeteksi ping timeout setelah 3x percobaan retry berturut-turut. Insiden telah diselesaikan saat kabel dipasang kembali.','high','resolved'),(3,7,'2026-10-12 13:22:43','[SIMULASI] Service Health Failure','[DATA UJI / SIMULASI KEGAGALAN] Service web monitoring dan daemon REST API dihentikan sementara untuk menguji HTTP health check. Endpoint mengembalikan HTTP status 503 Service Unavailable. Layanan telah direstart dan tiket insiden ditutup.','critical','closed'),(5,11,'2026-10-12 14:32:43','[SIMULASI] Power Cut / Heartbeat Timeout','[DATA UJI / SIMULASI KEGAGALAN] Catu daya mikrokontroler ESP32 dilepas untuk menguji deteksi offline sensor lab. Tidak ada paket heartbeat telemetry yang diterima sistem selama lebih dari 180 detik. Status insiden masih terbuka (open).','medium','open'),(6,11,'2026-10-14 18:53:34','Device Offline','Device IOT-ESP-01 (ESP32 Monitoring Panel Surya) tidak merespons sejak 2026-10-13 23:29:48','medium','open'),(7,16,'2026-10-14 18:53:34','Device Offline','Device NET-RTR-02 (Router Marketing Office) tidak merespons sejak 2026-10-14 00:20:52','high','resolved'),(8,17,'2026-10-14 18:53:34','Device Offline','Device SEC-CCTV-01 (CCTV Head Office) tidak merespons sejak 2026-10-14 00:58:02','high','resolved'),(9,19,'2026-10-14 18:53:34','Device Offline','Device DISP-TV-01 (Smart TV Xiaomi Head Office) tidak merespons sejak 2026-10-14 00:20:53','medium','resolved'),(10,20,'2026-10-14 18:53:34','Device Offline','Device PC-WS-01 (PC Head Office 01) tidak merespons sejak 2026-10-14 00:20:53','medium','resolved'),(11,22,'2026-10-14 18:53:34','Device Offline','Device IOT-RPI-01 (Raspberry Pi Smart Home) tidak merespons sejak 2026-10-13 23:52:15','medium','open'),(12,16,'2026-10-15 11:01:53','Device Offline','Device NET-RTR-02 (Router Marketing Office) ti